import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import './RegistrationForm.css';

function RegistrationStep2() {
  const [formData, setFormData] = useState({
    height: '',
    heightUnit: '',
    weight: '',
    weightUnit: '',
    desiredWeight: '',
    sex: '',
    dob: ''
  });

  const navigate = useNavigate();

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    // Retrieve step 1 data from localStorage
    const step1Data = JSON.parse(localStorage.getItem('registrationStep1'));
    const completeFormData = { ...step1Data, ...formData };

    try {
      await axios.post('/users', completeFormData);
      navigate('/login');
    } catch (error) {
      alert('Error registering user');
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <h2>Register - Step 2</h2>
      <div>
        <label>Height:</label>
        <input
          type="text"
          name="height"
          value={formData.height}
          onChange={handleChange}
          placeholder="Enter your height"
        />
      </div>
      <div>
        <label>Height Unit:</label>
        <input
          type="text"
          name="heightUnit"
          value={formData.heightUnit}
          onChange={handleChange}
          placeholder="Enter height unit (e.g., cm)"
        />
      </div>
      <div>
        <label>Weight:</label>
        <input
          type="text"
          name="weight"
          value={formData.weight}
          onChange={handleChange}
          placeholder="Enter your weight"
        />
      </div>
      <div>
        <label>Weight Unit:</label>
        <input
          type="text"
          name="weightUnit"
          value={formData.weightUnit}
          onChange={handleChange}
          placeholder="Enter weight unit (e.g., kg)"
        />
      </div>
      <div>
        <label>Desired Weight:</label>
        <input
          type="text"
          name="desiredWeight"
          value={formData.desiredWeight}
          onChange={handleChange}
          placeholder="Enter your desired weight"
        />
      </div>
      <div>
        <label>Sex:</label>
        <input
          type="text"
          name="sex"
          value={formData.sex}
          onChange={handleChange}
          placeholder="Enter your sex"
        />
      </div>
      <div>
        <label>Date of Birth:</label>
        <input
          type="date"
          name="dob"
          value={formData.dob}
          onChange={handleChange}
        />
      </div>
      <button type="submit">Register</button>
    </form>
  );
}

export default RegistrationStep2;
